import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
const context=vm.createContext({});vm.runInContext(fs.readFileSync('students/analysis-core-20261030.js','utf8'),context);const A=context.MT_ANALYSIS,evaluate=x=>{if(x.a<0||x.b<0)throw Error('Positive domain');return {results:{product:x.a*x.b,zero:x.a-x.b},curves:[]};};let checks=0;
const input={a:4,b:4};const rows=A.sensitivity(evaluate,input,'product');for(const row of rows){assert.ok(Math.abs(row.elasticity-1)<1e-12);checks++;}const zero=A.sensitivity(evaluate,input,'zero');assert.ok(zero.every(r=>r.elasticity===null));checks++;assert.deepEqual(input,{a:4,b:4});checks++;
const map=await A.heatmap(evaluate,input,'product',{path:['a'],min:-1,max:2},{path:['b'],min:1,max:4},{size:4,yieldTask:async()=>{}});assert.equal(map.length,16);assert.equal(map.filter(r=>r.error).length,4);for(const cell of map.filter(r=>!r.error)){assert.equal(cell.value,cell.x*cell.y);checks++;}await assert.rejects(A.heatmap(evaluate,input,'product',{path:['a'],min:0,max:1},{path:['a'],min:0,max:1}),/different/);checks++;
await assert.rejects(A.heatmap(evaluate,input,'product',{path:['a'],min:0,max:1},{path:['b'],min:0,max:1},{cancel:()=>true}),/cancelled/);checks++;
const a={curves:[{id:'p',xLabel:'m',yLabel:'N',series:[{name:'q',points:[{x:1,y:2}]}]}]},b={curves:[{id:'p',xLabel:'m',yLabel:'N',series:[{name:'q',points:[{x:3,y:20}]}]}]};const overlay=A.curves(a,b);assert.equal(overlay[0].series[0].dashed,false);assert.equal(overlay[0].series[1].dashed,true);assert.equal(overlay[0].series[1].points[0].y,20);assert.equal(A.curves(a,{curves:[{...b.curves[0],xLabel:'s'}]}).length,0);checks+=4;console.log(JSON.stringify({status:'PASS',checks,scope:'Independent product elasticity, zero baseline, domain cells, cancellation, immutable input and common physical axes.'}));
